import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { allTools } from '../registry/index.js';
import { describeTool } from '../registry/tools.js';
/** Markdown inventory: a tool table, then one section per tool listing its actions. */
export function renderToolsDoc(tools) {
    const lines = [];
    lines.push('# Tool inventory');
    lines.push('');
    lines.push('Generated by `npm run gen:tools` from the tool registry. Do not edit by hand.');
    lines.push('');
    lines.push('| Tool | Actions |');
    lines.push('|---|---|');
    for (const t of tools)
        lines.push(`| \`${t.name}\` | ${Object.keys(t.actions).join(', ')} |`);
    lines.push('');
    for (const t of tools) {
        lines.push(`## \`${t.name}\``);
        lines.push('');
        lines.push(describeTool(t));
        lines.push('');
        for (const [name, def] of Object.entries(t.actions))
            lines.push(`- \`${name}\` — ${def.describe}`);
        lines.push('');
    }
    return lines.join('\n');
}
export function writeToolsDoc(root) {
    const file = path.join(root, 'docs', 'tools.md');
    fs.writeFileSync(file, renderToolsDoc(allTools()));
    return file;
}
const entry = process.argv[1] ? pathToFileURL(path.resolve(process.argv[1])).href : '';
if (entry === import.meta.url) {
    const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
    const file = writeToolsDoc(root);
    process.stdout.write(`wrote ${path.relative(root, file)}\n`);
}
